result.text:
    if layout == "dense":
        input_response = _input_response_dense(model, backend, fixture)
        output_response = {
            "weighted": _output_response_dense(
                model, backend, fixture, use_scale_weight=True
            ),
            "presence": _output_response_dense(
                model, backend, fixture, use_scale_weight=False
            ),
        }
    else:
        input_response = _input_response_lower(model, backend, fixture)
        output_response = {
            "weighted": _output_response_lower(
                model, backend, fixture, use_scale_weight=True
            ),
            "presence": _output_response_lower(
                model, backend, fixture, use_scale_weight=False
            ),
        }
    return {"input": input_response, "output": output_response}


def _flatten_response_values(observations: dict[str, Any], field: str) -> list[float]:
    values: list[float] = []
    for scenario in observations.values():
        values.append(float(scenario["input"][field]))
        for mode in scenario["output"].values():
            values.append(float(mode[field]))
    return values


def _status_from_observations(observations: dict[str, Any]) -> str:
    background_values = _flatten_response_values(
        observations, "background_response_max_abs"
    )
    signal_values = _flatten_response_values(observations, "signal_response_max_abs")
    if not all(np.isfinite(background_values + signal_values)):
        return "runner_failure"
    if max(background_values) > 0.0:
        return "pre_fix_expected_failure"
    if min(signal_values) > 0.0:
        return "post_fix_success"
    return "workflow_completed"


def run_workflow() -> dict[str, Any]:
    observations: dict[str, Any] = {}
    for backend in ("numpy", "torch"):
        model = _build_model(backend)
        for dense_name in ("middle", "tail"):
            observations[f"{backend}_dense_{dense_name}"] = _scenario_observation(
                model, backend, "dense", _dense_fixture(dense_name)
            )
        observations[f"{backend}_lower"] = _scenario_observation(
            model, backend, "lower", _lower_fixture()
        )

    background_values = _flatten_response_values(
        observations, "background_response_max_abs"
    )
    signal_values = _flatten_response_values(observations, "signal_response_max_abs")
    return {
        "status": _status_from_observations(observations),
        "summary": {
            "scenario_count": len(observations),
            "max_background_response": max(background_values),
            "min_signal_response": min(signal_values),
            "output_modes": ["weighted", "presence"],
        },
        "observations": observations,
    }


def main() -> int:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    report_path = OUTPUT_DIR / "report.json"
    try:
        report = run_workflow()
        report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
        print(json.dumps(report, indent=2))
        return 1 if report["status"] == "runner_failure" else 0
    except Exception as exc:  # pragma: no cover - runner fallback
        report = {
            "status": "runner_failure",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
        report_path.write_text(json.dumps(report, indent=2), encoding="utf-8")
        print(json.dumps(report, indent=2))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
